-- Default CRM role templates: one source of truth, seeded for every NEW org,
-- and brought up to date for existing orgs' default roles.
--
-- Before this the nine default roles were inserted ONCE (20260706123952) for the
-- orgs that existed that day, with empty permissions, and filled by a series of
-- backfills. Nothing created them for a new org, so a new customer's non-admin
-- users could do nothing until roles were built by hand.
--
-- Template changes vs the roles as they stood:
--   * Owner and Operations Manager hold the entire permission catalog
--     (src/types/crm-roles.ts).
--   * Office Admin gains every scheduling/job-costing report (sched_rpt_*).
--   * Accounting gains job_view and sched_dispatch_board.
--   * Crew Leader keeps My Day, Driver Safety and Calculators dashboards; Fertilizer
--     Tech keeps My Day and Calculators. Both had every dashboard (Company Report,
--     KPIs, Job Costing, ...), which field roles don't need.
--   * Every template carries ONLY catalog keys. The legacy keys that are no longer
--     in the catalog were dropped from the default roles; none is read by app code,
--     a database function or an RLS policy, so no access changes.
--
-- Existing orgs: default-named roles are topped up ADDITIVELY (permissions ||
-- template) and the unreferenced legacy keys removed, so a box an admin ticked
-- on a default role stays ticked -- except the dashboard keys removed from Crew
-- Leader / Fertilizer Tech above, which are deliberately taken away. Roles an
-- admin created themselves (any other name) are not touched. Admins bypass every
-- check, so they are unaffected.

create or replace function public.crm_default_role_templates()
returns table(name text, description text, permissions jsonb)
language sql
immutable
set search_path to 'public'
as $$
