-- Seeds the default roles for one org. Idempotent: an org that already has a
-- role of that name keeps it. Not callable by clients; the trigger and
-- migrations run it with the owner's rights.
create or replace function public.seed_default_crm_roles(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  insert into public.crm_roles (org_id, name, description, permissions)
  select p_org_id, t.name, t.description, t.permissions
  from public.crm_default_role_templates() t
  where not exists (
    select 1 from public.crm_roles r
    where r.org_id = p_org_id and r.name = t.name and r.deleted_at is null
  );
end;
$$;

revoke execute on function public.seed_default_crm_roles(uuid) from public, anon, authenticated;
revoke execute on function public.crm_default_role_templates() from public, anon;

create or replace function public.fn_seed_default_crm_roles()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  perform public.seed_default_crm_roles(new.id);
  return new;
end;
$$;

revoke execute on function public.fn_seed_default_crm_roles() from public, anon, authenticated;

drop trigger if exists trg_seed_default_crm_roles on public.organizations;
create trigger trg_seed_default_crm_roles
  after insert on public.organizations
  for each row execute function public.fn_seed_default_crm_roles();

-- Existing orgs: add any default role that is missing...
select public.seed_default_crm_roles(o.id) from public.organizations o;

-- ...and top up the ones that exist: keep only catalog keys (the Owner template
-- IS the full catalog), then layer the template on top.
update public.crm_roles r
set permissions = (
      select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
      from jsonb_each(coalesce(r.permissions, '{}'::jsonb)) e
      where e.key in (
        select jsonb_object_keys(o.permissions)
        from public.crm_default_role_templates() o
        where o.name = 'Owner'
      )
    ) || t.permissions,
    updated_at = now()
from public.crm_default_role_templates() t
where r.name = t.name and r.deleted_at is null;

-- Crew Leader / Fertilizer Tech: take away the dashboards a field role doesn't need.
-- (The additive step above can't remove a key an older seed granted.)
update public.crm_roles r
set permissions = r.permissions - array['view_dashboard_company_report', 'view_dashboard_custom', 'view_dashboard_driver_safety', 'view_dashboard_equipt', 'view_dashboard_estimate_builder', 'view_dashboard_job_costing', 'view_dashboard_kpis', 'view_dashboard_reports', 'view_dashboard_social_media']::text[]
    || (select t.permissions from public.crm_default_role_templates() t where t.name = r.name),
    updated_at = now()
where r.deleted_at is null and r.name in ('Crew Leader', 'Fertilizer Tech');

notify pgrst, 'reload schema';
